// server/src/services/auth.service.ts
import { prisma } from '../lib/prisma';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { config } from '../utils/config';
import { AppError } from '../middleware/error-handler';

export class AuthService {
  async register(data: { email: string; name: string; password: string }) {
    const existingUser = await prisma.user.findUnique({
      where: { email: data.email },
    });

    if (existingUser) {
      throw new AppError('Bu email adresi zaten kayıtlı', 409);
    }

    const hashedPassword = await bcrypt.hash(data.password, 10);

    const user = await prisma.user.create({
      data: {
        email: data.email,
        name: data.name,
        password: hashedPassword,
      },
      select: {
        id: true,
        email: true,
        name: true,
        createdAt: true,
      },
    });

    const tokens = this.generateTokens(user.id);

    return { user, ...tokens };
  }

  async login(email: string, password: string) {
    const user = await prisma.user.findUnique({ where: { email } });

    if (!user) {
      throw new AppError('Email veya parola hatalı', 401);
    }

    const isPasswordValid = await bcrypt.compare(password, user.password);

    if (!isPasswordValid) {
      throw new AppError('Email veya parola hatalı', 401);
    }

    const tokens = this.generateTokens(user.id);

    return {
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
      },
      ...tokens,
    };
  }

  async refreshToken(token: string) {
    try {
      const payload = jwt.verify(token, config.jwtSecret) as { userId: string; type: string };

      if (payload.type !== 'refresh') {
        throw new AppError('Geçersiz token tipi', 401);
      }

      const user = await prisma.user.findUnique({ where: { id: payload.userId } });
      if (!user) throw new AppError('Kullanıcı bulunamadı', 401);

      return this.generateTokens(user.id);
    } catch {
      throw new AppError('Geçersiz refresh token', 401);
    }
  }

  private generateTokens(userId: string) {
    const accessToken = jwt.sign(
      { userId, type: 'access' },
      config.jwtSecret,
      { expiresIn: config.jwtExpiresIn }
    );

    const refreshToken = jwt.sign(
      { userId, type: 'refresh' },
      config.jwtSecret,
      { expiresIn: config.jwtRefreshExpiresIn }
    );

    return { accessToken, refreshToken };
  }
}

