// client/src/components/kanban-board.tsx
import { useState } from 'react';
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragStartEvent,
  DragEndEvent,
  DragOverEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';
import { SortableCard } from './sortable-card';
import { KanbanCard } from './kanban-card';

export function KanbanBoard({ board }: { board: any }) {
  const [activeCard, setActiveCard] = useState<any>(null);
  const queryClient = useQueryClient();

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 },
    }),
    useSensor(KeyboardSensor)
  );

  const moveCard = useMutation({
    mutationFn: async (data: { cardId: string; listId: string; position: number }) => {
      await api.put(`/cards/${data.cardId}/move`, {
        targetListId: data.listId,
        newPosition: data.position,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['board', board.id] });
    },
  });

  function handleDragStart(event: DragStartEvent) {
    const { active } = event;
    const card = findCard(active.id as string);
    setActiveCard(card);
  }

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    setActiveCard(null);

    if (!over) return;

    const activeCard = findCard(active.id as string);
    if (!activeCard) return;

    const overList = findListForCard(over.id as string);
    if (!overList) return;

    const overIndex = overList.cards.findIndex((c: any) => c.id === over.id);

    moveCard.mutate({
      cardId: activeCard.id,
      listId: overList.id,
      position: overIndex >= 0 ? overIndex : overList.cards.length,
    });
  }

  function findCard(id: string) {
    for (const list of board.lists) {
      const card = list.cards.find((c: any) => c.id === id);
      if (card) return card;
    }
    return null;
  }

  function findListForCard(id: string) {
    return board.lists.find((l: any) =>
      l.cards.some((c: any) => c.id === id)
    ) || board.lists.find((l: any) => l.id === id);
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="flex gap-4 overflow-x-auto p-6">
        {board.lists.map((list: any) => (
          <div key={list.id} className="w-72 flex-shrink-0 rounded-xl bg-gray-100 p-3 dark:bg-gray-800">
            <h3 className="mb-3 font-semibold">{list.title}</h3>
            <SortableContext
              items={list.cards.map((c: any) => c.id)}
              strategy={verticalListSortingStrategy}
            >
              <div className="space-y-2">
                {list.cards.map((card: any) => (
                  <SortableCard key={card.id} card={card} />
                ))}
              </div>
            </SortableContext>
          </div>
        ))}
      </div>

      <DragOverlay>
        {activeCard ? (
          <div className="rotate-3 opacity-90">
            <KanbanCard card={activeCard} />
          </div>
        ) : null}
      </DragOverlay>
    </DndContext>
  );
}

// client/src/components/sortable-card.tsx
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { KanbanCard } from './kanban-card';

export function SortableCard({ card }: { card: any }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: card.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners}>
      <KanbanCard card={card} />
    </div>
  );
}

// handleDragOver - KanbanBoard component'ine ekle
function handleDragOver(event: DragOverEvent) {
  const { active, over } = event;
  if (!over) return;

  const activeId = active.id as string;
  const overId = over.id as string;

  const activeList = findListForCard(activeId);
  const overList = findListForCard(overId) || board.lists.find((l: any) => l.id === overId);

  if (!activeList || !overList || activeList.id === overList.id) return;

  // Optimistic update: kartı lokal state'te taşı
  queryClient.setQueryData(['board', board.id], (old: any) => {
    if (!old) return old;

    const newLists = old.lists.map((list: any) => {
      if (list.id === activeList.id) {
        return {
          ...list,
          cards: list.cards.filter((c: any) => c.id !== activeId),
        };
      }
      if (list.id === overList.id) {
        const card = activeList.cards.find((c: any) => c.id === activeId);
        const overIndex = list.cards.findIndex((c: any) => c.id === overId);
        const newCards = [...list.cards];
        newCards.splice(overIndex >= 0 ? overIndex : newCards.length, 0, card);
        return { ...list, cards: newCards };
      }
      return list;
    });

    return { ...old, lists: newLists };
  });
}

// DndContext'e onDragOver ekle:
// <DndContext onDragOver={handleDragOver} ...>

// Gelişmiş handleDragEnd
function handleDragEnd(event: DragEndEvent) {
  const { active, over } = event;
  setActiveCard(null);

  if (!over) {
    // Geçersiz yere bırakıldı - state'i geri al
    queryClient.invalidateQueries({ queryKey: ['board', board.id] });
    return;
  }

  const activeId = active.id as string;
  const overId = over.id as string;

  // Aynı pozisyon - bir şey yapma
  if (activeId === overId) return;

  const overList = findListForCard(overId) || board.lists.find((l: any) => l.id === overId);
  if (!overList) return;

  const overIndex = overList.cards.findIndex((c: any) => c.id === overId);
  const newPosition = overIndex >= 0 ? overIndex : overList.cards.length;

  moveCard.mutate(
    {
      cardId: activeId,
      listId: overList.id,
      position: newPosition,
    },
    {
      onError: () => {
        // API hatası - cache'i gerçek veriye geri döndür
        queryClient.invalidateQueries({ queryKey: ['board', board.id] });
      },
    }
  );
}

